    [6713]={name="Ripped Pants",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'Burning Blade Medallion' - pick it over the other choices. In Valley of Trials.",zone="Valley of Trials",questName="Burning Blade Medallion",lore="Through my divinations, I see that an item of power hides deep within the Burning Blade Coven, guarded by beasts and black magic. It is called the Burning Blade Medallion, and your next task is to find it and remove it from the coven."},
    [6744]={name="Gloves of Kapelan",quality=2,ilvl=33,sourceType="quest_reward",instructions="Reward from the quest 'Alliance Relations' - pick it over the other choices. In Orgrimmar.",zone="Orgrimmar",questName="Alliance Relations",lore="The fight goes well. Perhaps the Warchief will allow us to return to our homes before the seasons change if we continue to make such great strides in our battle against the demons and their underlings."},
    [6803]={name="Prophetic Cane",quality=3,ilvl=44,sourceType="quest_reward",instructions="Reward from the quest 'Into The Scarlet Monastery' - pick it over the other choices. In Scarlet Monastery.",zone="Scarlet Monastery",questName="Into The Scarlet Monastery",lore="Whilst the Dark Lady tends to the pressing issue of the Lich King's advance to the north, I am seeing to it that matters closer to home are being taken care of accordingly."},
    [6806]={name="Dancing Flame",quality=3,ilvl=40,sourceType="quest_reward",instructions="Reward from the quest 'Final Passage' - pick it over the other choices. In Thousand Needles.",zone="Thousand Needles",questName="Final Passage",lore="You have done well. You have passed my test, and the tests before mine. Return to Dorn in Thousand Needles."},
