    [6908]={name="Ghamoo-ra's Bind",quality=3,ilvl=25,reqLevel=20,sourceType="boss_drop",instructions="Drops from Ghamoo-ra in Blackfathom Deeps.",zone="Blackfathom Deeps",npc="Ghamoo-ra",lore="Ghamoo-ra is the ancient turtle the naga keep in Blackfathom Deeps -- old enough that the Twilight cultists there treat it as part of the temple."},
