    [6998]={name="Nimbus Boots",quality=2,ilvl=25,sourceType="quest_reward",instructions="Reward from the quest 'Twilight Falls'. In Blackfathom Deeps.",zone="Blackfathom Deeps",questName="Twilight Falls",lore="Empowered by the ancient rites of the chaotic Old Gods the members of the Twilight's Hammer strive to bring about the return of their dark patrons and spread death and terror across the world."},
    [7001]={name="Gravestone Scepter",quality=3,ilvl=29,sourceType="quest_reward",instructions="Reward from the quest 'Blackfathom Villainy' - pick it over the other choices. In Blackfathom Deeps.",zone="Blackfathom Deeps",questName="Blackfathom Villainy",lore="Strength has left me. Your help is needed! Long ago this site was a great temple of Elune. But misfortune led to ruin when the corruption of an Old God seeped up from beneath the earth and tainted the sacred Moon Well."},
    [7004]={name="Prelacy Cape",quality=2,ilvl=27,sourceType="quest_reward",instructions="Reward from the quest 'Researching the Corruption' - pick it over the other choices. In Blackfathom Deeps.",zone="Blackfathom Deeps",questName="Researching the Corruption",lore="Foolish blood elves toil with demonic magic. Have they not witnessed what happened with the naga and with the satyrs of Kalimdor? I fear that the blood elves will meet a similar deformation."},
