    [11187]={name="Stemleaf Bracers",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'The Balance of Nature' - pick it over the other choices. In Shadowglen.",zone="Shadowglen",questName="The Balance of Nature",lore="Greetings. I am Conservator Ilthalaine. My purpose in Shadowglen is to ensure that the balance of nature is maintained."},
    [11189]={name="Woodland Robes",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'Webwood Egg' - pick it over the other choices. In Shadowglen.",zone="Shadowglen",questName="Webwood Egg",lore="Now that I have the spiders' venom, I'd like some live specimens to study. Unfortunately, capturing a living, giant spider is more than I can ask of you, young."},
