    [11848]={name="Flax Belt",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'Scavenging Deathknell' - pick it over the other choices. In Deathknell.",zone="Deathknell",questName="Scavenging Deathknell",lore="You there! If you're looking for something to make yourself useful, then listen up! We need fresh out-of-the-ground recruits to head into Deathknell and search for any sort of useful equipment."},
    [11855]={name="Tork Wrench",quality=2,ilvl=19,sourceType="quest_reward",instructions="Reward from the quest 'Samophlange Manual' - pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Samophlange Manual",lore="I think I can fix the samophlange, but I'm going to need the user's manual first."},
    [11904]={name="Spirit of Aquementas",quality=2,ilvl=56,sourceType="quest_reward",instructions="Reward from the quest 'It's Dangerous to Go Alone' - pick it over the other choices. In Un'Goro Crater.",zone="Un'Goro Crater",questName="It's Dangerous to Go Alone",lore="I finally remember now... I did come here to fight Blazerunner. I was on a journey, and this was to be the last step. But I am no longer the hero..."},
