    [12295]={name="Leggings of the People's Militia",quality=2,ilvl=15,sourceType="quest_reward",instructions="Reward from the quest 'Red Leather Bandanas' - pick it over the other choices. In Westfall.",zone="Westfall",questName="Red Leather Bandanas",lore="The Defias Front is constantly shifting. I've been following their movements for quite some time now. On a side note, I've ascertained that many members of the gang can be tracked by the Red Leather Bandanas they wear."},
