    [15444]={name="Staff of Orgrimmar",quality=2,ilvl=18,sourceType="quest_reward",instructions="Reward from the quest 'Hidden Enemies' - pick it over the other choices. In Orgrimmar.",zone="Orgrimmar",questName="Hidden Enemies",lore="You are one of my lieutenants! Prepare yourself. I will call upon you soon. My time spent on the Searing Blade may be all but wasted now, but that does not mean that the Shadow Council's schemes elsewhere must suffer."},
