    [16605]={name="Friar's Robes of the Light",quality=2,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'Garments of the Light'.",questName="Garments of the Light",lore="Normally I put forth a small challenge to followers of the Light to test their skill."},
    [16606]={name="Juju Hex Robes",quality=2,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'Garments of Spirituality'.",questName="Garments of Spirituality",lore="You be ready for your first test. South of Razor Hill, just outta town, one of our grunts be hurt fightin' off some o' Proudmoore's old troops."},
    [16607]={name="Acolyte's Sacrificial Robes",quality=2,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'Garments of Darkness'.",questName="Garments of Darkness",lore="Our power comes from darkness and shadow, but that is not your only role. You have acknowledged that there is merit in knowing the healing arts."},
    [16697]={name="Devout Bracers",quality=3,ilvl=57,reqLevel=52,sourceType="boss_drop",instructions="Drops from Crimson Priest in Stratholme.",zone="Stratholme",npc="Crimson Priest"},
    [16791]={name="Silkstream Cuffs",quality=2,ilvl=38,sourceType="quest_reward",instructions="Reward from the quest 'Book of the Ancients' - pick it over the other choices. In Desolace.",zone="Desolace",questName="Book of the Ancients",lore="I entrust you with the Gem of the Serpent. Place this gem on the Serpent Statue's hand on Ranazjar Isle, a small island northwest of here. Placing it will summon the one who protects the Book of the Ancients."},
    [16887]={name="Witch's Finger",quality=3,ilvl=30,sourceType="quest_reward",instructions="Reward from the quest 'Baron Aquanis' - pick it over the other choices. In Ashenvale.",zone="Ashenvale",questName="Baron Aquanis",lore="The defeated water elemental has left behind a strange water globe. You surmise that the object somehow fed the beast energy. Inside the globe, a putrid-looking form of water sloshes about."},
    [16894]={name="Clear Crystal Rod",quality=2,ilvl=21,sourceType="quest_reward",instructions="Reward from the quest 'Arachnophobia' - pick it over the other choices. In Stonetalon Mountains.",zone="Stonetalon Mountains",questName="Arachnophobia",lore="Warning: Proceed into Sishir Canyon west of here at your own risk. Besseleth and her eight-legged children of the forest have claimed this canyon as their webbed lair."},
    [16919]={name="Boots of Transcendence",quality=4,ilvl=76,reqLevel=60,sourceType="boss_drop",instructions="Drops from Broodlord Lashlayer in Blackwing Lair.",zone="Blackwing Lair",npc="Broodlord Lashlayer",lore="Nefarian's lieutenant, posted to hold the only way deeper into the lair."},
    [16920]={name="Handguards of Transcendence",quality=4,ilvl=76,reqLevel=60,sourceType="boss_drop",instructions="Drops from Ebonroc in Blackwing Lair.",zone="Blackwing Lair",npc="Ebonroc",lore="One of three drakes guarding Nefarian's inner lair, and the one that heals itself off the wounds it deals."},
    [16921]={name="Halo of Transcendence",quality=4,ilvl=76,reqLevel=60,sourceType="boss_drop",instructions="Drops from Onyxia in Onyxia's Lair.",zone="Onyxia's Lair",npc="Onyxia",lore="Deathwing's daughter and Nefarian's sister. She spent years in Stormwind as Lady Katrana Prestor, advising the throne she was working to undermine."},
    [16922]={name="Leggings of Transcendence",quality=4,ilvl=76,reqLevel=60,sourceType="boss_drop",instructions="Drops from Ragnaros.",npc="Ragnaros",lore="The Firelord, one of the four Elemental Lords, bound to the Elemental Plane until the Dark Iron dwarves summoned him under Blackrock Mountain. The summoning cracked the mountain open and made the Molten Core."},
    [16923]={name="Robes of Transcendence",quality=4,ilvl=76,reqLevel=60,sourceType="boss_drop",instructions="Drops from Nefarian.",npc="Nefarian",lore="Deathwing's son, working under Blackrock Mountain to breed the chromatic flight -- dragons carrying the blood of all five. He spent years in Stormwind's court as Lord Victor Nefarius while the work went on."},
    [16924]={name="Pauldrons of Transcendence",quality=4,ilvl=76,reqLevel=60,sourceType="boss_drop",instructions="Drops from Chromaggus in Blackwing Lair.",zone="Blackwing Lair",npc="Chromaggus",lore="Nefarian's best result: a two-headed chromatic horror carrying the breath of every dragonflight at once."},
