    [16981]={name="Owlbeard Bracers",quality=2,ilvl=20,sourceType="quest_reward",instructions="Reward from the quest 'Earthen Arise' - pick it over the other choices. In Stonetalon Mountains.",zone="Stonetalon Mountains",questName="Earthen Arise",lore="You have uncovered a dark threat to the land. The Resonite cask you have found in that cave houses a slumbering Earthen by the name of Goggeroc."},
