    [19118]={name="Nature's Breath",quality=2,ilvl=50,sourceType="quest_reward",instructions="Reward from the quest 'Dark Vessels'. In The Hinterlands.",zone="The Hinterlands",questName="Dark Vessels",lore="The Vilebranch fight with supernatural ferocity. This is due to the foul magical weavings of the Vile Priestess Hexx. Throughout Jintha'alor you will find dark vessels of tainted blood."},
