    [21186]={name="Rockfury Bracers",quality=4,ilvl=62,sourceType="quest_reward",instructions="Reward from the quest 'Stalwart's Battlegear' - pick it over the other choices. In Silithus.",zone="Silithus",questName="Stalwart's Battlegear",lore="The badges you collect from performing combat, logistics and tactical assignments for Windcaller Proudhorn are more than just for show. You'd be wise to hold on to them."},
    [21348]={name="Tiara of the Oracle",quality=4,ilvl=81,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Tiara of the Oracle'. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Tiara of the Oracle",lore="The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity. They mock me, knowing I cannot step further into their domain to save my brother Arygos."},
    [21350]={name="Mantle of the Oracle",quality=4,ilvl=78,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Mantle of the Oracle'. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Mantle of the Oracle",lore="It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon."},
